/*
 * Per-interface default vtbl storage.  Populated by
 * npt_id3d11devicecontext4_install_default_vtbl(), which is called once at
 * runtime init time from the global client_table init function.
 */
struct npt_id3d11devicecontext4_client_vtbl npt_id3d11devicecontext4_default_vtbl_storage;

void
npt_id3d11devicecontext4_install_default_vtbl(void)
{
    npt_id3d11devicecontext4_fill_default_vtbl(&npt_id3d11devicecontext4_default_vtbl_storage);
}

void *
npt_id3d11devicecontext4_client_create(struct npt_device *dev, uint64_t host_id)
{
    struct npt_com_base *p = (struct npt_com_base *)npt_alloc(sizeof(*p));
    if (!p)
        return NULL;
    npt_com_base_init(p,
        (const void **)&npt_id3d11devicecontext4_default_vtbl_storage,
        dev, host_id);
    return p;
}


